public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int somme = 0;
        int n = Integer.parseInt(sc.nextLine());
        while (n != 0) {
            n = Integer.parseInt(sc.nextLine());
            somme += n;
        }
        System.out.println("Somme : " + somme);
